(function facts() {
  const map = window.__shiokRouteMap, debug = window.__shiokRouteDebug;
  const rect = element => { const r = element?.getBoundingClientRect(); return r && { x:r.x, y:r.y, width:r.width, height:r.height, right:r.right, bottom:r.bottom }; };
  const features = map.queryRenderedFeatures({ layers:['shiokest-route-line'] });
  const style = map.isStyleLoaded();
  return { key:debug.routeKey, count:features.filter(f => f.properties.render_key === debug.routeKey).length,
    width:innerWidth, height:innerHeight, moving:map.isMoving(), center:map.getCenter().toArray(), zoom:map.getZoom(),
    style, basemap:style && map.isSourceLoaded('onemap'), tiles:style && map.areTilesLoaded(),
    status:document.querySelector('main')?.dataset.mapStatus, overflow:document.documentElement.scrollWidth > innerWidth,
    brand:rect(document.querySelector('h1')), search:rect(document.querySelector('#postal-search-input').closest('form')),
    sheet:rect(document.querySelector('aside')), about:rect([...document.querySelectorAll('summary')].find(n=>n.textContent==='About data')) };
})()

